#!/usr/bin/env python3
"""Write reviewed records from the user's second leaderboard source batch."""
from pathlib import Path
from cmu_rag.io import digest, read_jsonl, write_jsonl

OUT=Path('data/raw/leaderboard-source-batch2/documents.jsonl')
CHECKED='2026-10-25'
FACTS=[
('1','Monday Night Open Mic Comedy — The Getaway','https://thegetawaypgh.com/event/monday-night-open-mic-comedy/2023-05-22/','The Getaway Bar & Grill','Historical listing: The Getaway Bar & Grill listed Monday Night Open Mic Comedy on May 22, 2023, from 8:00 to 10:00 p.m. The page says the series ran every Monday in that time slot. The venue is listed at 3049 Sussex Ave, Pittsburgh, PA 15226. This is a past event, not a current schedule. Source: The Getaway event listing.'),
('5','CMU Navlab — autonomous and assisted driving','https://www.cs.cmu.edu/afs/cs/project/alv/www/','Carnegie Mellon University Navlab','CMU Navlab builds computer-controlled vehicles for automated and assisted driving. Its official page says the group has built a series of robot cars, vans, SUVs, and buses since 1984. More recent research includes smart infrastructure, machine vision, and affordable sensors. The page describes Navlab 11 as a sensor-equipped robot Jeep Wrangler. Source: Carnegie Mellon University.'),
('6','täkō Pittsburgh restaurant status and cuisine','https://takopgh.com/','täkō Pittsburgh','täkō describes its downtown Pittsburgh restaurant as a fusion of Mexican and Japanese street-food flavors, with tequila and mezcal. When checked October 25, 2026, its homepage stated “Temporarily closed for in-restaurant dining” and referred visitors to updates about renovation progress. Verify current operating status before relying on older material. Source: official täkō website.'),
('10','Robert Morris men’s basketball regular-season titles','https://rmucolonials.com/sports/2025/5/20/history','Robert Morris University Athletics','Robert Morris Athletics lists these men’s basketball regular-season championship seasons: 1982, 1983, 1984, 1989, 1990, 1992, 2008, 2009, 2010, 2013, 2014, and 2025 — 12 seasons in the page’s list. Source: official Robert Morris athletics history page; the page also includes championships in other sports.'),
('11','2026 Phil Steele strength-of-schedule rankings: Syracuse and Pitt','https://fbschedules.com/college-football-strength-of-schedule-phil-steeles-2026-rankings/','FBSchedules','In the 2026 Phil Steele strength-of-schedule rankings published by FBSchedules, Syracuse is ranked 42nd and Pittsburgh (Pitt) 63rd. This source does not support a claim that Syracuse ranked 16th. The ranking is edition-specific and should not be treated as a current or universal schedule-strength ranking. Source: FBSchedules.'),
('27','Chuck Noll Steelers coaching years','https://www.steelers.com/history/bios/noll_chuck','Pittsburgh Steelers','The Steelers’ official Chuck Noll biography lists his Pittsburgh head-coaching career as 1969–1991 and says he was hired in 1969. It therefore does not support 1964 as the hiring year. Source: Steelers.com.'),
('47','McKees Rocks Bridge length and county record','https://www.spcregion.org/2024/01/19/post-gazette-state-local-officials-announce-132-million-for-repairs-to-three-pittsburgh-bridges/','Southwestern Pennsylvania Commission','The Southwestern Pennsylvania Commission reports that McKees Rocks Bridge is the longest bridge in Allegheny County. Including its longest elevated ramp, it is nearly 7,300 feet long. It connects McKees Rocks with Pittsburgh’s Brighton Heights neighborhood. Source: SPC, reporting on bridge rehabilitation.'),
('73','Scotty Saturday and CMU Family Weekend','https://www.cmu.edu/student-affairs/sit/traditions/scotty-saturday.html','Carnegie Mellon University','Carnegie Mellon describes Scotty Saturday as an annual campus-spirit event co-hosted by the Office of Student Involvement and Traditions and the Office of Family Engagement during CMU’s annual Family Weekend. The 2026 page lists the event on October 3, 2026. Source: CMU Student Affairs.'),
('88','H. J. Heinz founding location and incorporation','https://www.sec.gov/Archives/edgar/data/46640/000095012309014732/l35859ae10vk.htm','H. J. Heinz Company 2009 Form 10-K','H. J. Heinz Company’s SEC-filed 2009 Form 10-K says the company was incorporated in Pennsylvania on July 27, 1900, and in 1905 succeeded to a partnership business that had developed from a food business founded in 1869 in Sharpsburg, Pennsylvania by Henry J. Heinz. This supports Sharpsburg as the original business location, not Pittsburgh. Source: SEC filing.'),
('34','Iron Born Pizza and Detroit-style pizza','https://ironbornpizza.com/','Iron Born Pizza','Iron Born Pizza’s official story says its chef first tasted Detroit-style pizza while on vacation in Colorado, then spent a year researching and experimenting before launching the restaurant concept. The page calls the product square pizza and lists locations in Millvale and Pittsburgh’s Strip District. Source: Iron Born Pizza.'),
('15','Fiddlesticks: Once Upon a Melody','https://pittsburghsymphony.org/production/107728/fiddlesticks-once-upon-a-melody','Pittsburgh Symphony Orchestra','The Pittsburgh Symphony Orchestra lists “Fiddlesticks: Once Upon a Melody” at Heinz Hall on November 14, 2026 at 11:15 a.m. The family concert invites young listeners to help create a fairy tale through music. Source: Pittsburgh Symphony Orchestra official event page.'),
('49','Detre Library & Archives','https://www.heinzhistorycenter.org/research/detre-library-archives/','Senator John Heinz History Center','The Thomas & Katherine Detre Library & Archives is part of the Senator John Heinz History Center. The History Center describes it as Western Pennsylvania’s preeminent source for researching the region’s history. Its page links to search, digital collections, research visits, reproductions, and other archival resources. Source: Heinz History Center.'),
('138','Pittsburgh Pirates postseason return','https://www.mlb.com/pirates/history/records-stats-awards/postseason-results','Pittsburgh Pirates / MLB','The official Pirates postseason results list a 2013 National League Wild Card game against Cincinnati, which Pittsburgh won 6–2, followed by a 2013 NL Division Series against St. Louis. This records the club’s return to postseason play in 2013. Source: MLB/Pittsburgh Pirates.'),
('108','Great Fire of Pittsburgh, April 10, 1845','https://www.heinzhistorycenter.org/blog/western-pennsylvania-history-of-bells-and-fire-artifacts-recall-april-10-1845/','Senator John Heinz History Center','The Heinz History Center says the Great Fire of Pittsburgh occurred on April 10, 1845. A fire near Ferry Street spread for nearly seven hours and consumed more than 1,000 buildings. The History Center’s article describes the old City Hall bell’s annual tolling of “1-8-4-5” in commemoration. Source: Heinz History Center.'),
('139','CMU College of Fine Arts Building','https://www.cmu.edu/visit/campus-tours/self-guided-campus-tour','Carnegie Mellon University','CMU’s self-guided campus tour describes the College of Fine Arts Building as designed by Henry Hornbostel, the college’s first dean. The building houses the Schools of Architecture, Art, and Music, along with four BXA intercollege degree programs. Source: CMU Visit.'),
]

def main():
    OUT.parent.mkdir(parents=True,exist_ok=True)
    rows=[]
    for q,title,url,source,text in FACTS:
        rows.append({'id':'leaderboard-source-b2-'+digest(q+'\n'+url+'\n'+text)[:24],
          'kind':'curated_source_record','source':'user-second-source-batch','url':url,'aliases':[url],
          'title':title,'text':text,'text_hash':digest(text),'source_checked_on':CHECKED,
          'user_provided_question_ids':q.split(','),'extractor':'browser-reviewed-source-extract-v1',
          'provenance':[{'page_url':url,'method':'verified public-page text reviewed in browser'}]})
    old=read_jsonl(OUT) if OUT.exists() else []
    by_id={r['id']:r for r in old}
    by_id.update({r['id']:r for r in rows})
    write_jsonl(OUT,by_id.values())
    print(f'Wrote {len(rows)} source extracts to {OUT}')
if __name__=='__main__': main()
